      "id": 1,
      "claim": "In a DFS tree of a connected undirected graph, every non-tree edge is a back edge connecting a vertex to one of its ancestors.",
      "evidence": "Standard property of DFS in undirected graphs: no cross edges exist. If an edge (u,v) is not a tree edge, one endpoint must be an ancestor of the other.",
      "weight": 0.35,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Given a non-tree edge (u, v) with pre(u) < pre(v), u must be an ancestor of v in T.",
      "evidence": "Since the edge connects an ancestor-descendant pair and u is discovered before v (lower preorder number), u is the ancestor. If v were the ancestor, pre(v) would be less than pre(u).",
      "weight": 0.35,
      "depends_on": [
        1
      ]
    },
    {
      "id": 3,
      "claim": "Statement II ('u is an ancestor of v in T') is true.",
      "evidence": "Derived directly from Step 2. This is a necessary truth for any such edge.",
      "weight": 0.1,
      "depends_on": [
        2
      ]
    },
    {
      "id": 4,
      "claim": "Statement III ('If w is the lowest common ancestor of u and v in T, then w = u') is true.",
      "evidence": "By definition, if u is an ancestor of v, the lowest common ancestor of u and v is u itself (the deepest node that is an ancestor of both).",
      "weight": 0.1,
      "depends_on": [
        2
      ]
    },
    {
      "id": 5,
      "claim": "Statement I ('post(u) < post(v)') is false.",
      "evidence": "In postorder traversal, a descendant is visited before its ancestor. Since v is a descendant of u, post(v) < post(u). Therefore, post(u) > post(v).",
      "weight": 0.1,
      "depends_on": [
        2
      ]
    }
